fn main() {
    // The main window loads the Host's own origin, which Tauri treats as a
    // *remote* IPC origin. App commands are unreachable from a remote origin
    // unless the app declares an ACL manifest, so every command the webview
    // may call is listed here; the generated `allow-<command>` permissions
    // (in `permissions/autogenerated/`, gitignored) are what the
    // `capabilities/*.json` files then grant, per origin.
    tauri_build::try_build(
        tauri_build::Attributes::new().app_manifest(
            tauri_build::AppManifest::new().commands(&[
                "server_status",
                "restart_server_cmd",
                "check_update_cmd",
                "quit_app",
                "open_external",
            ]),
        ),
    )
    .expect("failed to run tauri-build");
}
